import {isRotatable} from './orientations.mjs';
import {renderEquipment,renderMilestones,renderVariantOptions,furniturePreview} from './progression-ui.mjs';
import {progressForXP,pendingMilestones,levelForXP} from './progression.mjs';
import {CATALOG,PRESETS,EQUIPMENT,WALLS,FLOORS,APPEARANCES} from './catalog.mjs';
import {activeStationEquipmentId,stationPatient} from './interactions.mjs';
export const STAGES={toReception:'Heading to reception',checkIn:'Checking in',waiting:'Waiting patiently',toExam:'On the way to the doctor',seating:'Taking a seat',exam:'Having an eye exam',standing:'Getting ready to leave',toPayment:'Heading to the counter',payment:'Paying for their visit',exiting:'A brighter day ahead'};
const $=s=>document.querySelector(s);
const button=(action,text,cls='secondary',disabled=false,value='')=>`<button class="${cls}" data-action="${action}" ${value!==''?`data-value="${value}"`:''} ${disabled?'disabled':''}>${text}</button>`;
export function createUI(root,handlers){let panelKey='',patientsKey='',lastView;const click=e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;handlers.action(b.dataset.action,b.dataset.value,b);};document.addEventListener('click',click);
function preview(key,v){const s=v.manifest?.sprites?.[key];if(!s)return '<span class="catalog-symbol">✧</span>';const f=v.manifest.files[s.sheet];return `<svg class="sprite-preview" viewBox="${s.rect.join(' ')}" aria-hidden="true"><image href="${f.file}" width="${f.width}" height="${f.height}"/></svg>`;}
function equipment(w,v){return renderEquipment(w.clinic,v.manifest);}
function placement(v){if(!v.tool&&!v.finishDirty)return '';const name=v.tool?CATALOG[v.tool.kind]?.name??'Your furnishing':'New finishes';return `<div class="placement-controls"><strong>${name}</strong>${v.tool?`<div class="customization-summary"><span id="orientation-status">${isRotatable(v.tool.kind)?`${v.tool.rotation+1} / 4`:'Mounted to wall'}</span><span>${v.purchase?`Purchase · ✦ ${v.price} coins`:'Owned · Free'}</span></div>`:''}<p class="${v.valid?'':'invalid'}" role="status">${v.message||'Tap a clear tile in your practice.'}</p>${v.tool&&['chair','counter','exam','display'].includes(v.tool.kind)?'<small class="access-legend">● Patient access · ◆ Staff access</small>':''}<div class="placement-buttons">${v.tool&&isRotatable(v.tool.kind)?button('rotate-back','↶ Back')+button('rotate','↻ Rotate'):''}${button('confirm','✓ Confirm','primary',!v.valid)}${button('cancel-edit','Cancel')}</div>${v.tool?.id&&!CATALOG[v.tool.kind].core?button('store','Return to inventory','secondary store-item'):''}</div>`;}
function build(w,v){const c=v.draft?.clinic??w.clinic;const tabs=['Furniture','Finishes','Equipment','Inventory'];let content=`<span class="panel-eyebrow">MAKE YOURSELF AT HOME</span><h2>A little more you.</h2><p class="panel-description">The clinic is paused. Tap furniture to move it, or choose something lovely below.</p><div class="build-tabs">${tabs.map(t=>button('build-tab',t,v.tab===t.toLowerCase()?'active':'',false,t.toLowerCase())).join('')}</div>`;
if(v.tab==='furniture'){content+=`<div class="catalog-grid">${['chair','plant','rug','cabinet','art'].map(kind=>{const d=CATALOG[kind],count=c.items.filter(i=>i.kind===kind).length;return `<button class="catalog-item ${v.tool?.kind===kind&&!v.tool.id?'selected':''}" data-action="catalog" data-value="${kind}" ${count>=d.limit?'disabled':''}><span class="item-art">${furniturePreview({kind,variantId:'default',rotation:0},v.manifest)}</span><strong>${d.name}</strong><small>✦ ${d.price} · ${count}/${d.limit} owned</small></button>`}).join('')}</div><p class="panel-description" style="margin-top:13px">Your counter, exam station and glasses display are already included. Tap them in the room to move them.</p>`;}
if(v.tab==='finishes'){for(const [name,list,key]of [['Walls',WALLS,'wall'],['Floors',FLOORS,'floor']])content+=`<section class="swatch-section"><h3>${name} · always free</h3><div class="swatches">${list.map(f=>`<button class="swatch ${c[key+'Id']===f.id?'selected':''}" data-action="${key}" data-value="${f.id}" ${levelForXP(c.xp)<f.unlockLevel?'disabled':''} aria-label="${f.name}${levelForXP(c.xp)<f.unlockLevel?' · Level '+f.unlockLevel:''}"><span style="background:${f.color}${f.id==='checker'?';background:conic-gradient(#b9c3aa 25%,#eee8d6 0 50%,#b9c3aa 0 75%,#eee8d6 0);background-size:16px 16px':''}"></span>${f.name}${levelForXP(c.xp)<f.unlockLevel?' · Level '+f.unlockLevel:''}</button>`).join('')}</div></section>`;}
if(v.tab==='equipment')content+=equipment(w,v);
if(v.tab==='inventory'){const inv=c.items.filter(i=>i.x===null);content+=inv.length?inv.map(i=>button('inventory',`${CATALOG[i.kind].name} · Place for free`,'inventory-entry',false,i.id)).join(''):'<p class="panel-description" style="margin-top:20px">Nothing tucked away yet. Return decorations to inventory to use them again later.</p>';content+='<h3 style="margin-top:20px">Placed furnishings</h3><p class="panel-description">Select any item to move it or return decorations to inventory.</p>'+c.items.filter(i=>i.x!==null).map(i=>button('placed',CATALOG[i.kind].name+' · Select','inventory-entry',false,i.id)).join('');}
return content+(v.tool?renderVariantOptions(c,v.tool,v.manifest):'')+placement(v);}
function play(w,v){const selected=w.patients.find(p=>p.id===v.selectedPatient);return `<span class="panel-eyebrow">A LITTLE CARE GOES A LONG WAY</span><h2>Good things take care.</h2><p class="panel-description">Your neighbors are in good hands. Watch your little practice find its rhythm.</p><div class="summary-row"><span>Happy patients</span><strong>${w.clinic.completedVisits}</strong></div><div class="summary-row"><span>In the practice</span><strong>${w.patients.length} / 8</strong></div><div class="summary-row"><span>Waiting seats</span><strong>${w.clinic.items.filter(i=>i.kind==='chair'&&i.x!==null).length}</strong></div><div class="exam-progress" aria-hidden="true"><span id="exam-bar" style="width:0"></span></div><div class="exam-caption" id="exam-caption" role="status">Ready for your next patient</div>${button('pause',v.manualPaused?'▷ Resume practice':'Ⅱ Pause for a moment','secondary full pause-button')}${equipment(w,v)}${button('open-objects','Inspect clinic objects','secondary full object-list-button')}${button('new-game','↺ Start a new practice','text-btn full new-practice-button')}${selected?`<div class="cozy-message"><strong>${APPEARANCES[selected.appearance].name}</strong><br>${STAGES[selected.stage]}</div>`:'<div class="cozy-message">♡ No rush, no penalties. Everyone is happy to wait a little.</div>'}`;}
function inspect(w,v){const item=w.clinic.items.find(i=>i.id===v.selectedObject);if(!item)return play(w,v);const active=stationPatient(w);let detail='A little piece of your practice.';
if(item.kind==='exam')detail=active?`${APPEARANCES[active.appearance].name} · ${STAGES[active.stage]}`:'The doctor is ready for a neighbor.';
else if(item.kind==='counter'){const p=w.patients.find(p=>p.id===w.counter);detail=p?`${APPEARANCES[p.appearance].name} · ${STAGES[p.stage]}`:'Ready for check-in and payment.';}
else if(item.kind==='chair'){const p=w.patients.find(p=>p.seatId===item.id);detail=p?`${APPEARANCES[p.appearance].name} has this seat.`:'A comfortable seat, ready for someone.';}
return `<span class="panel-eyebrow">OBJECT DETAILS</span><h2>${CATALOG[item.kind].name}</h2><p class="panel-description" id="object-status">${detail}</p>${item.kind==='exam'?'<div class="exam-progress" aria-hidden="true"><span id="exam-bar" style="width:0"></span></div><div id="exam-caption" class="exam-caption" role="status"></div>'+equipment(w,v):''}${item.kind==='exam'&&activeStationEquipmentId(w)!==w.clinic.equipmentId?'<p class="panel-description">New equipment is ready. The current patient will finish with their original kit.</p>':''}${renderVariantOptions(w.clinic,item,v.manifest)}<div class="object-actions">${button('move-object','✧ Customize','secondary full',false,item.id)}</div>${item.kind==='exam'?'<p class="panel-description">Patient and doctor positions follow this station when it is rotated or moved.</p>':''}`;}
function render(w,v){const session=v.editSession;v={...v,tool:session?session.candidate:null,draft:session?.draft??v.finishDraft,finishDirty:!!v.finishDraft,valid:session?.result.ok??v.finishValid,message:v.message||(session?(session.result.ok?'Ready to confirm. Your changes stay in preview until then.':session.result.reason):''),purchase:session?.mode==='purchase',price:session?.cost??0,cursor:session?.candidate};lastView=v;if(!w)return;const c=w.clinic;const xp=progressForXP(c.xp);$('#hud-level').textContent='Level '+xp.level;$('#hud-xp').textContent=xp.nextThreshold===null?c.xp+' XP · All milestones':c.xp+' / '+xp.nextThreshold+' XP';$('#xp-fill').style.width=(xp.fraction*100)+'%';$('#xp-hud').setAttribute?.('aria-label','Level '+xp.level+', '+c.xp+' total XP. View milestones.');const pending=pendingMilestones(c)[0];$('#milestone-note').hidden=!pending;if(pending){$('#milestone-title').textContent='Level '+pending.level+' · '+pending.name;$('#milestone-unlocks').textContent=pending.unlocks;$('#milestone-ack').dataset.value=pending.id;}$('#control-panel').hidden=!v.panelOpen;$('#patient-strip').hidden=v.panel!=='patients';$('#hud-patients').textContent=c.completedVisits+' helped';for(const [id,panel]of [['dock-practice','practice'],['dock-build','build'],['dock-equipment','equipment'],['dock-patients','patients']])$('#'+id).classList.toggle('active',v.panelOpen&&v.panel===panel);$('#coin-count').textContent=c.coins.toLocaleString();$('#clinic-name').textContent=PRESETS[c.presetId].name;$('#play-state').textContent=v.mode==='customize'?'Taking a decorating break':v.manualPaused?'A little pause':'Open & feeling cozy';$('#build-banner').hidden=v.mode!=='customize';$('#play-tab').classList.toggle('active',v.mode==='play');$('#build-tab').classList.toggle('active',v.mode==='customize');$('#canvas-help').textContent=v.mode==='customize'?'Tap a furnishing or choose an item · Tap a tile to place':'Drag to look around · + and − to zoom';
const key=JSON.stringify([v.mode,v.tab,v.tool,v.cursor,v.valid,v.message,v.finishDirty,v.manualPaused,c.coins,c.equipmentId,c.ownedEquipmentIds,c.xp,c.acknowledgedMilestoneIds,c.completedVisits,c.items,v.draft?.clinic,v.selectedPatient,v.selectedObject,v.panel,v.panelOpen,w.patients.map(p=>[p.id,p.stage]),!!v.manifest]);if(key!==panelKey){panelKey=key;const focused=document.activeElement;const action=focused?.dataset?.action,value=focused?.dataset?.value;$('#control-content').innerHTML=`<div class="panel-inner">${v.mode==='customize'?build(w,v):v.panel==='object'?inspect(w,v):v.panel==='equipment'?'<span class="panel-eyebrow">BETTER TOOLS, BRIGHTER DAYS</span><h2>Your exam equipment.</h2>'+equipment(w,v):v.panel==='milestones'?renderMilestones(c):v.panel==='objects'?'<span class="panel-eyebrow">TAP TO INSPECT</span><h2>Inside your practice.</h2>'+w.clinic.items.filter(i=>i.x!==null).map(i=>button('inspect-object',CATALOG[i.kind].name,'inventory-entry',false,i.id)).join(''):v.panel==='patients'?'<span class="panel-eyebrow">PATIENT STATUS</span><h2>Your friendly neighbors.</h2>':play(w,v)}</div>`;if(action&&focused&&!focused.isConnected){const found=[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===action&&b.dataset.value===value&&!b.disabled);found?.focus({preventScroll:true});}}
const exam=w.patients.find(p=>['exam','toExam','seating','standing'].includes(p.stage));if($('#exam-bar'))$('#exam-bar').style.width=exam?`${Math.round((1-exam.examRemaining/exam.examDuration)*100)}%`:'0';if($('#exam-caption'))$('#exam-caption').textContent=exam?(exam.stage==='toExam'?'Your next patient is on the way':exam.stage==='seating'?'Your patient is taking a seat':exam.stage==='standing'?'All done. Your patient is getting up':`${APPEARANCES[exam.appearance].name}’s exam · ${Math.ceil(exam.examRemaining)}s remaining`):'A moment of quiet. The doctor is ready.';
const pk=JSON.stringify(w.patients.map(p=>[p.id,p.stage]));if(pk!==patientsKey){patientsKey=pk;$('#patient-list').innerHTML=w.patients.length?w.patients.map(p=>{const a=APPEARANCES[p.appearance];return `<button class="patient-chip" data-action="patient" data-value="${p.id}" style="--patient-color:${a.color}"><span>${a.name[0]}</span><div><strong>${a.name}</strong><small>${STAGES[p.stage]}</small></div></button>`;}).join(''):'<span class="patient-empty">A new friendly face will be along soon.</span>';}}
return {render,refresh(){panelKey='';patientsKey='';},destroy(){document.removeEventListener('click',click);}};}
